# BEGIN COMPUTER REGISTRY
# Computer inventory and coordinated client rollouts. Additive tables only.
def init_computers(c):
    c.executescript('''
    CREATE TABLE IF NOT EXISTS retail_computers(id TEXT PRIMARY KEY,hostname TEXT NOT NULL,macs TEXT NOT NULL,os TEXT NOT NULL,name TEXT NOT NULL DEFAULT '',role TEXT NOT NULL DEFAULT 'office',registered INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 0,seen REAL NOT NULL);
    CREATE TABLE IF NOT EXISTS retail_computer_apps(app TEXT NOT NULL,device TEXT NOT NULL,computer TEXT NOT NULL REFERENCES retail_computers(id),version TEXT NOT NULL,status TEXT NOT NULL,seen REAL NOT NULL,ip TEXT NOT NULL,PRIMARY KEY(app,device));
    CREATE TABLE IF NOT EXISTS retail_computer_updates(app TEXT PRIMARY KEY,body TEXT NOT NULL);
    ''')

def computer_heartbeat(handler,app,d):
    meta=d.get('computer')
    if not isinstance(meta,dict) or not re.fullmatch('[a-f0-9]{32}',str(meta.get('id',''))):return
    ident=meta['id'];hostname=str(meta.get('hostname',''))[:120];system=str(meta.get('os',''))[:160]
    macs=meta.get('macs',[])
    if not isinstance(macs,list):raise Problem('Invalid computer information.')
    macs=sorted({str(m).upper() for m in macs[:16] if re.fullmatch(r'(?:[0-9a-fA-F]{2}:){5}[0-9a-fA-F]{2}',str(m))})
    with connect() as c:
        previous=c.execute('SELECT computer FROM retail_computer_apps WHERE app=? AND device=?',(app,d['device'])).fetchone()
        if previous and previous['computer']!=ident:raise Problem('This installation belongs to a different computer. Ask an administrator to review its registration.',409)
        c.execute('INSERT INTO retail_computers(id,hostname,macs,os,seen) VALUES(?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET hostname=excluded.hostname,macs=excluded.macs,os=excluded.os,seen=excluded.seen',(ident,hostname,json.dumps(macs),system,time.time()))
        c.execute('INSERT INTO retail_computer_apps VALUES(?,?,?,?,?,?,?) ON CONFLICT(app,device) DO UPDATE SET version=excluded.version,status=excluded.status,seen=excluded.seen,ip=excluded.ip',(app,d['device'],ident,d['version'],str(d.get('status','Connected'))[:200],time.time(),handler.client_address[0]))

def computer_campaign(c,app):
    row=c.execute('SELECT body FROM retail_computer_updates WHERE app=?',(app,)).fetchone()
    return json.loads(row['body']) if row else None

def computer_ticket(c,app,ident):
    job=computer_campaign(c,app)
    return job if job and secrets.compare_digest(job['id'],ident) else None

def computer_client_state(app,device,result):
    with connect() as c:
        job=computer_campaign(c,app)
        if job and device in job['targets']:
            member=c.execute('SELECT registered FROM retail_computers pc JOIN retail_computer_apps a ON a.computer=pc.id WHERE a.app=? AND a.device=?',(app,device)).fetchone()
            if member and member['registered']:result['campaign']=job
    return result

def computer_require_admin(u):
    if not u.get('admin'):raise Problem('Administrator access required to manage computers and updates.',403)

def computer_check(force=False):
    global POS_UPDATE_RELEASE,OFFICE_UPDATE_RELEASE
    if force or OPS_UPDATE_RELEASE.get('attempted',0)<time.time()-3600:
        with connect() as c:has_ops=c.execute("SELECT 1 FROM retail_computer_apps WHERE app='ops'").fetchone()
        if has_ops and not OPS_UPDATE_RELEASE.get('checking'):
            OPS_UPDATE_RELEASE.update(checking=True,attempted=time.time());threading.Thread(target=ops_update_check,daemon=True).start()
    for app in ('pos','office'):
        release=POS_UPDATE_RELEASE if app=='pos' else OFFICE_UPDATE_RELEASE
        if not release.get('checking') and (force or time.time()-release.get('attempted',release.get('checked',0))>3600):
            pending={**release,'checking':True,'attempted':time.time()}
            if app=='pos':POS_UPDATE_RELEASE=pending
            else:OFFICE_UPDATE_RELEASE=pending
            def check(kind=app,attempt=pending['attempted']):
                (pos_update_check if kind=='pos' else office_update_check)()
                with LOCK:(POS_UPDATE_RELEASE if kind=='pos' else OFFICE_UPDATE_RELEASE)['attempted']=attempt
            threading.Thread(target=check,daemon=True).start()

def computer_state(c,u,check=True):
    computer_require_admin(u)
    if check:computer_check()
    jobs={app:computer_campaign(c,app) for app in ('pos','office','ops')}
    releases={'pos':POS_UPDATE_RELEASE,'office':OFFICE_UPDATE_RELEASE,'ops':OPS_UPDATE_RELEASE};computers=[]
    for row in c.execute('SELECT * FROM retail_computers ORDER BY registered DESC,name,hostname'):
        pc=dict(row);pc['macs']=json.loads(pc['macs']);pc['apps']=[]
        for record in c.execute('SELECT * FROM retail_computer_apps WHERE computer=? ORDER BY app,device',(pc['id'],)):
            item=dict(record);item['online']=time.time()-item['seen']<60;job=jobs.get(item['app']);latest=releases[item['app']].get('version')
            item['available']=bool(latest and updater.version(latest)>updater.version(item['version']))
            item['target']=job['version'] if job and item['device'] in job['targets'] else None
            item['complete']=bool(item['target'] and updater.version(item['version'])>=updater.version(item['target']))
            item['progress']='Updated' if item['complete'] else ('Waiting for application to reconnect' if not item['online'] else item['status'])
            pc['apps'].append(item)
        computers.append(pc)
    return {'computers':computers,'releases':releases,'campaigns':jobs,'server_version':updater.current()}

def computer_post(handler,c,u,path,d):
    if path=='self':return computer_self(handler,c,u,d)
    computer_require_admin(u)
    if path=='register':
        ident=d.get('id');row=c.execute('SELECT * FROM retail_computers WHERE id=?',(ident,)).fetchone()
        if not row:raise Problem('Open DESK, STORE OPS or OFFICE on that computer and sign in first.',404)
        if d.get('revision')!=row['revision']:raise Problem('Computer registration changed. Refresh and try again.',409)
        name=str(d.get('name','')).strip();role=d.get('role','office')
        if not 1<=len(name)<=80 or role not in ('pos','office','server','other'):raise Problem('Enter a computer name and valid role.')
        computer_link_terminal(c,ident,d,name,row['hostname'])
        c.execute('UPDATE retail_computers SET name=?,role=?,registered=1,revision=revision+1 WHERE id=?',(name,role,ident))
        c.execute('INSERT INTO audit VALUES(?,?,?,?)',(dt.datetime.now().isoformat(timespec='seconds'),u['name'],'Registered or renamed computer',json.dumps({'id':ident,'name':name,'role':role})))
    elif path=='check':computer_check(True)
    elif path=='start':
        seconds=d.get('seconds',120);selected=d.get('computers')
        if type(seconds) is not int or not 30<=seconds<=3600:raise Problem('Choose a warning period of 30 to 3600 seconds.')
        if not isinstance(selected,list) or not selected or len(selected)>1000 or any(not isinstance(x,str) for x in selected):raise Problem('Select registered computers to update.')
        selected=set(selected);known={r['id'] for r in c.execute('SELECT id FROM retail_computers WHERE registered=1')}
        if not selected<=known:raise Problem('Register the selected computers first.')
        pending=[]
        for app,release in [('pos',POS_UPDATE_RELEASE),('office',OFFICE_UPDATE_RELEASE),('ops',OPS_UPDATE_RELEASE)]:
            if not any(r['computer'] in selected for r in c.execute('SELECT computer FROM retail_computer_apps WHERE app=?',(app,))):continue
            if release.get('checking') or release.get('error') or not release.get('version') or time.time()-release.get('checked',0)>3600:raise Problem('Finish checking the selected applications for updates first.',409)
            if app!='ops' and (pos_update_read() if app=='pos' else office_update_read()).get('campaign'):raise Problem('Cancel the existing '+app.upper()+' update request before starting a computer rollout.',409)
            old=computer_campaign(c,app)
            if old:
                versions={r['device']:r['version'] for r in c.execute('SELECT device,version FROM retail_computer_apps WHERE app=?',(app,))}
                if any(updater.version(versions.get(device,'0.0.0'))<updater.version(old['version']) for device in old['targets']):raise Problem('Complete or cancel the current rollout first.',409)
            targets=[r['device'] for r in c.execute('SELECT * FROM retail_computer_apps WHERE app=?',(app,)) if r['computer'] in selected and updater.version(r['version'])<updater.version(release['version'])]
            if targets:pending.append((app,{'id':secrets.token_hex(32),'mode':'notify','automatic':True,'version':release['version'],'seconds':seconds,'target':'registered','targets':targets,'by':u['name'],'at':time.time()}))
        if not pending:raise Problem('The selected applications are already up to date.')
        for app,job in pending:c.execute('INSERT OR REPLACE INTO retail_computer_updates VALUES(?,?)',(app,json.dumps(job)))
        c.execute('INSERT INTO audit VALUES(?,?,?,?)',(dt.datetime.now().isoformat(timespec='seconds'),u['name'],'Started registered computer rollout',json.dumps({'computers':sorted(selected),'seconds':seconds})))
    elif path=='cancel':
        c.execute('DELETE FROM retail_computer_updates')
        for read,save in ((pos_update_read,pos_update_save),(office_update_read,office_update_save)):
            legacy=read();legacy['campaign']=None;save(legacy)
        c.execute('INSERT INTO audit VALUES(?,?,?,?)',(dt.datetime.now().isoformat(timespec='seconds'),u['name'],'Canceled pending computer rollout','Installers already launched cannot be canceled.'))
    else:raise Problem('Unknown computer action.',404)
    c.commit()
    return handler.send(computer_state(c,u,False))


OPS_UPDATE_RELEASE={'checking':False}
def ops_update_check():
    try:
        repository='m404ntfd/mgc-yfc-operations'
        release=json.loads(updater.fetch('https://api.github.com/repos/'+repository+'/releases/latest',1000000))
        if release.get('draft') or release.get('prerelease'):raise ValueError('A stable release is required.')
        candidates=[]
        for asset in release.get('assets',[]):
            match=re.fullmatch(r'CoastYouth-Retail-STORE-OPS-Setup-v(\d+\.\d+\.\d+)\.exe',asset.get('name',''))
            if match and re.fullmatch(r'sha256:[a-f0-9]{64}',asset.get('digest') or ''):candidates.append((updater.version(match[1]),match[1],asset))
        if not candidates:raise ValueError('No verified STORE OPS installer is available.')
        _,version,asset=max(candidates)
        if not asset['browser_download_url'].startswith('https://github.com/'+repository+'/releases/download/'):raise ValueError('Unexpected installer address.')
        with LOCK:OPS_UPDATE_RELEASE.update(checking=False,version=version,url=asset['browser_download_url'],checked=time.time(),error=None)
    except Exception as e:
        with LOCK:OPS_UPDATE_RELEASE.update(checking=False,error=str(e))

def computer_self(handler,c,u,d):
    app=d.get('app');device=d.get('device');version=d.get('version')
    if app not in ('pos','office','ops') or not re.fullmatch('[a-f0-9]{32}',str(device)) or not re.fullmatch(r'\d+\.\d+\.\d+',str(version)):raise Problem('Invalid desktop identity.')
    meta=d.get('computer')
    if not isinstance(meta,dict) or not re.fullmatch('[a-f0-9]{32}',str(meta.get('id',''))):raise Problem('Windows computer identity is unavailable. Contact your administrator.')
    computer_heartbeat(handler,app,d)
    row=c.execute('SELECT * FROM retail_computers WHERE id=?',(meta['id'],)).fetchone()
    terminal=c.execute('SELECT id,name,enabled FROM retail_terminals WHERE device=?',(device,)).fetchone() if app=='pos' else None
    result={'computer':{k:row[k] for k in ('id','name','hostname','role','registered','revision')},'terminal':dict(terminal) if terminal else None}
    return handler.send(computer_client_state(app,device,result))

def computer_link_terminal(c,ident,d,name,hostname):
    # First-time DESK enrollment may link an available terminal, never replace an existing binding.
    device=d.get('device')
    if d.get('app')!='pos' or not device:return
    member=c.execute("SELECT 1 FROM retail_computer_apps WHERE computer=? AND app='pos' AND device=?",(ident,device)).fetchone()
    if not member:raise Problem('Refresh this computer before registering its checkout.',409)
    current=c.execute('SELECT * FROM retail_terminals WHERE device=?',(device,)).fetchone()
    if current:return
    target=d.get('terminal')
    if target:
        row=c.execute('SELECT * FROM retail_terminals WHERE id=?',(target,)).fetchone()
        if not row or row['device'] or not row['enabled']:raise Problem('Choose an enabled, unassigned terminal.',409)
        c.execute('UPDATE retail_terminals SET device=?,hostname=?,revision=revision+1 WHERE id=?',(device,hostname,target))
    else:
        if len(name)>60 or c.execute('SELECT 1 FROM retail_terminals WHERE name=? COLLATE NOCASE',(name,)).fetchone():raise Problem('Choose the existing terminal or enter a unique name of 60 characters or fewer.',409)
        c.execute('INSERT INTO retail_terminals VALUES(?,?,?,?,?,?,?)',(secrets.token_hex(16),name,device,None,1,1,hostname))

# END COMPUTER REGISTRY

POS_KIOSK_APPROVALS={}

def pos_kiosk_approval(c,u,d):
    if not u.get('admin'):raise Problem('An Operations administrator must approve exit-passcode changes.',403)
    device=d.get('device');nonce=d.get('nonce')
    if not isinstance(device,str) or not re.fullmatch('[0-9a-f]{32}',device) or not isinstance(nonce,str) or not re.fullmatch('[0-9a-f]{64}',nonce):raise Problem('Invalid checkout-computer request.')
    now=time.time()
    for key in list(POS_KIOSK_APPROVALS):
        if POS_KIOSK_APPROVALS[key]['expires']<now:POS_KIOSK_APPROVALS.pop(key,None)
    if len(POS_KIOSK_APPROVALS)>=500:raise Problem('Too many pending approvals. Try again shortly.',429)
    token=secrets.token_hex(32)
    POS_KIOSK_APPROVALS[hashlib.sha256(token.encode()).hexdigest()]={'device':device,'nonce':nonce,'name':u['name'],'expires':now+60}
    return {'token':token}

def pos_kiosk_redeem(c,d):
    token=d.get('token')
    if not isinstance(token,str) or not re.fullmatch('[0-9a-f]{64}',token):raise Problem('Invalid administrator approval.',403)
    key=hashlib.sha256(token.encode()).hexdigest();approval=POS_KIOSK_APPROVALS.get(key)
    if not approval or approval['expires']<time.time() or approval['device']!=d.get('device') or approval['nonce']!=d.get('nonce'):raise Problem('Administrator approval expired or belongs to another checkout computer.',403)
    POS_KIOSK_APPROVALS.pop(key,None)
    row=c.execute('SELECT admin FROM users WHERE name=?',(approval['name'],)).fetchone()
    if not row or not row['admin']:raise Problem('Administrator access is no longer available.',403)
    c.execute('INSERT INTO audit VALUES(?,?,?,?)',(dt.datetime.now().isoformat(timespec='seconds'),approval['name'],'Authorized POS exit-passcode setup/change on device '+approval['device'],''))
    c.commit()
    return {'admin':True,'device':approval['device'],'nonce':approval['nonce']}

def pos_post(handler,c,u,path,d):
    if path=='kiosk-approval':return handler.send(pos_kiosk_approval(c,u,d))
    if not has_permission(u,'use_pos'):raise Problem('Point of Sale permission required.',403)
    owner=u.get('receipt_owner')
    if not owner:raise Problem('Employee account required.',403)
    if path=='display-state':return customer_post(handler,c,u,path,d,None)
    operation=d.get('request')
    if not isinstance(operation,str) or not re.fullmatch('[0-9a-f]{32}',operation):raise Problem('A unique request is required.')
    payload=json.dumps([path,d],sort_keys=True,separators=(',',':'))
    previous=c.execute('SELECT * FROM pos_operations WHERE id=?',(operation,)).fetchone()
    if previous:
        if previous['owner']!=owner or previous['payload']!=payload:raise Problem('Request already used for another action.',409)
        return handler.send(json.loads(previous['result']))
    now=dt.datetime.now().astimezone().isoformat(timespec='seconds')
    def finish(result,action):
        c.execute('INSERT INTO pos_operations VALUES(?,?,?,?)',(operation,owner,payload,json.dumps(result)))
        c.execute('INSERT INTO audit VALUES(?,?,?,?)',(now,u['name'],action,''))
        c.commit()
        return handler.send(result)
    if path=='catalog-options-save':return finish(catalog_save(c,u,d),'Catalog categories and taxes saved')
    if path=='pickup-followup':return fulfillment_post(c,u,d,finish)
    if path in ('store-save','store-terminal','programs-save','member-save','drawer-open','drawer-move','drawer-close'):
        return stores_post(c,u,path,d,finish)
    if path in ('thrift-settings','thrift-customer-save','thrift-voucher-issue','thrift-pickup-save','thrift-intake-create','thrift-intake-restock'):
        return thrift_post(c,u,path,d,finish)
    if path in ('customer-settings-save','reservation-contact','reservation-preview','delivery-retry','display-pair'):
        return customer_post(handler,c,u,path,d,finish)
    if path in ('policies-save','refund-preview','refund'):
        return retail_finance_post(c,u,path,d,finish)
    if path in ('product-save','catalog-preview','catalog-import','print-routes','transfer-sale','adjustment-decision'):
        return retail_workflow_post(c,u,path,d,finish)
    if path in ('layout-save','terminal-save'):
        if not has_permission(u,'manage_pos'):raise Problem('Manage POS permission required.',403)
        ident=d.get('id') or secrets.token_hex(16)
        if not isinstance(ident,str) or not re.fullmatch('[0-9a-f]{32}',ident):raise Problem('Invalid identifier.')
        table='retail_layouts' if path=='layout-save' else 'retail_terminals'
        old=c.execute('SELECT * FROM '+table+' WHERE id=?',(ident,)).fetchone()
        if d.get('revision',0)!=(old['revision'] if old else 0):raise Problem('Changed by another administrator. Reopen this editor before saving.',409)
        revision=(old['revision'] if old else 0)+1
        if path=='layout-save':
            body={'name':pos_text(d.get('name'),'a layout name',80),'columns':pos_int(d.get('columns'),'columns',2,6),'groups':[]}
            groups=d.get('groups')
            if not isinstance(groups,list) or not 1<=len(groups)<=30:raise Problem('Use between 1 and 30 groups.')
            products={r[0] for r in c.execute('SELECT id FROM pos_products')}
            for group in groups:
                if not isinstance(group,dict):raise Problem('Invalid group.')
                color=group.get('color','')
                if not isinstance(color,str) or not re.fullmatch('#[0-9a-fA-F]{6}',color):raise Problem('Choose a button color.')
                items=group.get('products')
                if not isinstance(items,list) or len(items)>200 or any(not isinstance(x,str) or x not in products for x in items) or len(set(items))!=len(items):raise Problem('Choose unique catalog products.')
                body['groups'].append({'name':pos_text(group.get('name'),'a group name',60),'color':color,'products':items})
            c.execute('INSERT INTO retail_layouts VALUES(?,?,?) ON CONFLICT(id) DO UPDATE SET revision=excluded.revision,body=excluded.body',(ident,revision,json.dumps(body)))
        else:
            name=pos_text(d.get('name'),'a terminal name',60)
            device=d.get('device') or None
            if device and (not isinstance(device,str) or not re.fullmatch('[0-9a-f]{32}',device)):raise Problem('Invalid device identity.')
            layout=d.get('layout') or None
            if layout and not c.execute('SELECT 1 FROM retail_layouts WHERE id=?',(layout,)).fetchone():raise Problem('Choose an existing layout.')
            if type(d.get('enabled')) is not bool:raise Problem('Choose terminal status.')
            if old and old['device'] and device!=old['device']:raise Problem('A registered device cannot be reassigned. Disable the old terminal and register a new one.',409)
            if c.execute('SELECT 1 FROM retail_terminals WHERE id<>? AND (name=? COLLATE NOCASE OR (device IS NOT NULL AND device=?))',(ident,name,device)).fetchone():raise Problem('That terminal name or device is already registered.',409)
            hostname=d.get('hostname','')
            if not isinstance(hostname,str) or len(hostname)>120:raise Problem('Invalid computer name.')
            c.execute('INSERT INTO retail_terminals VALUES(?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,device=excluded.device,layout=excluded.layout,enabled=excluded.enabled,revision=excluded.revision,hostname=excluded.hostname',(ident,name,device,layout,int(d['enabled']),revision,hostname))
        return finish({'id':ident,'revision':revision},'Retail '+path+' '+ident)
    if path in ('account-create','account-adjust'):
        pos_credit_access(u,True)
        if path=='account-create':
            kind=d.get('kind')
            if kind not in ('customer','employee'):raise Problem('Choose customer or employee.')
            employee=None;name=pos_text(d.get('name'),'an account name')
            if kind=='employee':
                employee=pos_text(d.get('employee'),'an employee',64)
                profile=c.execute('SELECT p.name FROM receipt_profiles p JOIN users u ON u.name=p.name WHERE p.profile_id=?',(employee,)).fetchone()
                if not profile:raise Problem('Choose a current employee.')
                if c.execute('SELECT 1 FROM pos_credit_accounts WHERE employee=?',(employee,)).fetchone():raise Problem('This employee already has a store-credit account.',409)
                name=profile['name']
            contact=d.get('contact','')
            if not isinstance(contact,str) or len(contact)>200:raise Problem('Contact/reference must be at most 200 characters.')
            ident=c.execute('INSERT INTO pos_credit_accounts(name,kind,employee,contact) VALUES(?,?,?,?)',(name,kind,employee,contact.strip())).lastrowid
        else:
            ident=pos_int(d.get('account'),'account',1);account=pos_credit_account(c,ident)
            if c.execute('SELECT 1 FROM retail_gifts WHERE account=?',(ident,)).fetchone():raise Problem('Gift balances change through purchase, redemption, and original-tender refunds only.')
            if c.execute('SELECT 1 FROM thrift_vouchers WHERE account=?',(ident,)).fetchone():raise Problem('Assistance voucher balances change through issuance, redemption and refunds only.')
            if d.get('account_revision')!=account['revision']:raise Problem('Balance changed. Refresh the account before adjusting.',409)
            amount=pos_int(d.get('amount'),'adjustment amount',1)
            if d.get('direction') not in ('add','subtract'):raise Problem('Choose add or subtract.')
            amount*=1 if d['direction']=='add' else -1
            balance=account['balance']+amount
            if not 0<=balance<=10000000:raise Problem('Balance must remain between $0 and $100,000.')
            reason=pos_text(d.get('reason'),'an adjustment reason/reference',500)
            c.execute('INSERT INTO pos_credit_ledger(account,amount,balance,at,actor,reason) VALUES(?,?,?,?,?,?)',(ident,amount,balance,now,u['name'],reason))
        return finish({'account':pos_credit_account(c,ident)},'Store-credit '+path+' AC'+str(ident).zfill(6))
    if path=='settings':
        if not has_permission(u,'manage_pos'):raise Problem('Manage POS permission required.',403)
        if d.get('confirmed') is not True:raise Problem('Confirm the store tax rate before enabling checkout.')
        settings={'store':pos_text(d.get('store'),'a receipt store name'),'tax_bps':pos_int(d.get('tax_bps'),'tax rate',0,10000),'currency':'USD'}
        c.execute('INSERT OR REPLACE INTO pos_settings VALUES(1,?)',(json.dumps(settings),))
        return finish({'settings':settings},'POS settings saved')
    if path=='product':
        if not has_permission(u,'manage_pos'):raise Problem('Manage POS permission required.',403)
        product={'name':pos_text(d.get('name'),'an item name'),'category':pos_text(d.get('category'),'a category',60),'price':pos_int(d.get('price'),'price',1),'taxable':d.get('taxable')}
        if type(product['taxable']) is not bool:raise Problem('Choose taxable or non-taxable.')
        ident=secrets.token_hex(16)
        c.execute('INSERT INTO pos_products VALUES(?,?)',(ident,json.dumps(product)))
        return finish({'product':dict(id=ident,**product)},'POS catalog item added')
    if path=='new':
        store_id,registered=stores_context(c,u,d)
        settings=stores_settings(c,store_id)
        if settings['tax_bps'] is None:raise Problem('An administrator must configure POS tax and receipt settings first.',409)
        terminal=c.execute('SELECT name,enabled FROM retail_terminals WHERE device=?',(d.get('device',''),)).fetchone()
        if terminal and not terminal['enabled']:raise Problem('This terminal is disabled.',403)
        ident=secrets.token_hex(16);body={'store_id':store_id,'terminal_id':registered['id'] if registered else None,'lines':[],'subtotal':0,'tax':0,'total':0,'settings':settings,'terminal':terminal['name'] if terminal else '', 'held':False}
        c.execute('INSERT INTO pos_carts VALUES(?,?,1,?,?,?)',(ident,owner,'open',json.dumps(body),time.time()))
        return finish({'cart':dict(id=ident,revision=1,status='open',**body)},'POS cart started')
    ident=pos_text(d.get('cart'),'a cart identifier',32)
    row=c.execute('SELECT * FROM pos_carts WHERE id=? AND owner=?',(ident,owner)).fetchone()
    if not row:raise Problem('Cart not found.',404)
    cart=pos_cart(row)
    active_terminal=stores_terminal(c,d.get('device'))
    if active_terminal and (not active_terminal['enabled'] or active_terminal['store_id']!=stores_id(cart)):raise Problem('This saved sale belongs to another store or this terminal is disabled.',403)
    if row['status']!='open':raise Problem('This cart is already completed or discarded. Check sales history.',409)
    if d.get('revision')!=row['revision']:raise Problem('This cart changed in another tab. Reload it before continuing.',409)
    if path in ('hold','resume'):
        cart['held']=path=='hold';retail_save_cart(c,cart);retail_event(c,ident,u['name'],path,{})
        return finish({'cart':cart},'POS sale '+path)
    if path=='adjustment-request':
        if not cart['lines']:raise Problem('Add items before requesting an adjustment.')
        mode=d.get('mode')
        if mode not in ('discount','surcharge'):raise Problem('Choose discount or surcharge.')
        amount=pos_int(d.get('amount'),'adjustment',0,10000000);index=d.get('index')
        if index is not None:index=pos_int(index,'line number',0,len(cart['lines'])-1)
        request={'mode':mode,'amount':amount,'index':index,'reason':pos_text(d.get('reason'),'an adjustment reason',300),'requested_by':u['name'],'sale_total':cart['total'],'items':[{'name':l['name'],'quantity':l['quantity'],'subtotal':l['subtotal']} for l in cart['lines']]}
        request['percent_bps']=d.get('percent_bps')
        retail_check_adjustment(c,cart,request)
        if has_permission(u,'approve_pos_adjustments'):
            retail_adjust(c,cart,request,u['name']);return finish({'cart':cart},'POS adjustment approved')
        if c.execute("SELECT 1 FROM retail_adjustments WHERE cart=? AND status='pending'",(ident,)).fetchone():raise Problem('A request is already pending. Ask a manager to review it.',409)
        request_id=c.execute("INSERT INTO retail_adjustments(cart,revision,requested_by,body,status) VALUES(?,?,?,?,'pending')",(ident,cart['revision'],u['name'],json.dumps(request))).lastrowid
        retail_event(c,ident,u['name'],'adjustment-request',request)
        return finish({'approval':request_id},'POS adjustment requested')
    if cart.get('held') and path not in ('discard',):raise Problem('Resume this held sale before changing or completing it.',409)
    if path in ('thrift-tag','thrift-donation','thrift-customer','thrift-reward'):
        return thrift_cart_action(c,u,cart,path,d,finish)
    if path in ('gift-add','birthday-reward'):return stores_cart_action(c,u,cart,path,d,finish)
    if path in ('cash','credit'):
        if active_terminal:cart.update(terminal_id=active_terminal['id'],terminal=active_terminal['name'])
        stores_sale_prepare(c,cart,path)
        thrift_sale_prepare(c,cart,path)
    if path in ('add','remove'):
        if cart.get('reward'):raise Problem('Remove the loyalty reward before changing items.')
        if cart.get('adjustment'):raise Problem('Ask a manager to restore original prices before changing items.',409)
        lines=cart['lines']
        if path=='add':
            if len(lines)>=100:raise Problem('Maximum 100 lines per cart.')
            quantity=pos_int(d.get('quantity'),'quantity',1,999)
            if d.get('product'):
                item=stores_weight_line(c,cart,d) or retail_sale_item(c,pos_text(d['product'],'an item identifier',32),d.get('choices',{}),quantity,cart['settings']['tax_bps'],d.get('open_price'))
                catalog_stamp(c,item,cart['settings']['tax_bps'])
            else:
                item={'name':pos_text(d.get('name'),'an item name'),'category':pos_text(d.get('category'),'a category',60),'price':pos_int(d.get('price'),'price',1),'taxable':d.get('taxable')}
                if type(item['taxable']) is not bool:raise Problem('Choose taxable or non-taxable.')
                subtotal=item['price']*quantity;item.update(quantity=quantity,subtotal=subtotal,tax=(subtotal*cart['settings']['tax_bps']+5000)//10000 if item['taxable'] else 0)
            thrift_intake_line(c,cart,item)
            lines.append(item)
        else:
            index=pos_int(d.get('index'),'line number',0,len(lines)-1)
            lines.pop(index)
        cart['subtotal']=sum(x['subtotal'] for x in lines);cart['tax']=sum(x['tax'] for x in lines);cart['total']=cart['subtotal']+cart['tax']
        if cart['total']>10000000:raise Problem('Sale exceeds the $100,000 limit.')
        cart['revision']+=1
        body={k:v for k,v in cart.items() if k not in ('id','revision','status')}
        c.execute('UPDATE pos_carts SET body=?,revision=?,updated=? WHERE id=?',(json.dumps(body),cart['revision'],time.time(),ident))
        return finish({'cart':cart},'POS cart changed')
    if path=='discard':
        reason=pos_text(d.get('reason'),'a cancellation reason',300) if cart['lines'] else 'Empty cart'
        retail_event(c,ident,u['name'],'canceled',{'reason':reason,'total':cart['total']})
        c.execute("UPDATE pos_carts SET status='discarded',revision=revision+1 WHERE id=?",(ident,))
        return finish({'ok':True},'POS cart discarded')
    if path=='credit':
        pos_credit_access(u)
        if not has_permission(u,'use_store_credit'):raise Problem('Redeem store credit permission required.',403)
        if not cart['lines'] or cart['total']<=0:raise Problem('Add an item before checkout.')
        account=pos_credit_account(c,pos_int(d.get('account'),'account',1))
        if not account['active']:raise Problem('Account is inactive.',409)
        if d.get('account_revision')!=account['revision']:raise Problem('Balance changed. Refresh the account before paying.',409)
        amount=pos_int(d.get('amount'),'store credit',1,min(account['balance'],cart['total']))
        stores_credit_check(c,account,cart)
        thrift_voucher_check(c,account,cart,amount)
        remaining=cart['total']-amount
        tender=pos_int(d.get('tender'),'cash received',remaining,20000000 if remaining else 0)
        balance=account['balance']-amount
        sale={k:v for k,v in cart.items() if k not in ('id','revision','status')}
        sale.update(**retail_cash_change(cart['settings'],tender,remaining))
        sale.update(at=now,cashier=u['name'],method='store_credit_cash' if remaining else 'store_credit',tender=tender,store_credit=amount,credit_account=account['code'],credit_name=account['name'],credit_balance=balance)
        sale['receipt_design']=stores_profile(c,stores_id(sale))['receipt']
        sale_id=c.execute('INSERT INTO pos_sales(cart,owner,body) VALUES(?,?,?)',(ident,owner,json.dumps(sale))).lastrowid
        c.execute('INSERT INTO pos_credit_ledger(account,amount,balance,at,actor,reason,sale) VALUES(?,?,?,?,?,?,?)',(account['id'],-amount,balance,now,u['name'],'Payment for receipt #'+str(sale_id),sale_id))
        thrift_sale_saved(c,sale,sale_id)
        stores_sale_saved(c,sale,sale_id)
        fulfillment_saved(c,sale,sale_id)
        c.execute("UPDATE pos_carts SET status='paid',revision=revision+1 WHERE id=?",(ident,))
        return finish({'sale':dict(id=sale_id,**sale)},'POS store-credit sale completed #'+str(sale_id))
    if path=='cash':
        if not cart['lines'] or cart['total']<0:raise Problem('Add an item before checkout.')
        tender=pos_int(d.get('tender'),'cash received',cart['total'],20000000)
        sale={k:v for k,v in cart.items() if k not in ('id','revision','status')}
        sale.update(**retail_cash_change(cart['settings'],tender,cart['total']))
        sale.update(at=now,cashier=u['name'],method='cash',tender=tender)
        sale['receipt_design']=stores_profile(c,stores_id(sale))['receipt']
        sale_id=c.execute('INSERT INTO pos_sales(cart,owner,body) VALUES(?,?,?)',(ident,owner,json.dumps(sale))).lastrowid
        thrift_sale_saved(c,sale,sale_id)
        stores_sale_saved(c,sale,sale_id)
        fulfillment_saved(c,sale,sale_id)
        c.execute("UPDATE pos_carts SET status='paid',revision=revision+1 WHERE id=?",(ident,))
        return finish({'sale':dict(id=sale_id,**sale)},'POS cash sale completed #'+str(sale_id))
    raise Problem('Payment method or action is not available.',400)


def init():
    with connect() as c:
        c.executescript('''CREATE TABLE IF NOT EXISTS users(name TEXT PRIMARY KEY COLLATE NOCASE, salt TEXT, hash TEXT, admin INTEGER);
CREATE TABLE IF NOT EXISTS permissions(name TEXT PRIMARY KEY COLLATE NOCASE, can_create INTEGER NOT NULL DEFAULT 1, see_requests INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS photos(job TEXT, position INTEGER, body BLOB, PRIMARY KEY(job,position));
CREATE TABLE IF NOT EXISTS vehicles(name TEXT PRIMARY KEY COLLATE NOCASE);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY, revision INTEGER, body TEXT);
CREATE TABLE IF NOT EXISTS update_notices(id INTEGER PRIMARY KEY AUTOINCREMENT, version TEXT, actor TEXT, at TEXT);
CREATE TABLE IF NOT EXISTS daily_home(name TEXT COLLATE NOCASE, day TEXT, section TEXT, PRIMARY KEY(name,day));
CREATE TABLE IF NOT EXISTS landing_preferences(name TEXT PRIMARY KEY COLLATE NOCASE, section TEXT);
CREATE TABLE IF NOT EXISTS pages(id INTEGER PRIMARY KEY AUTOINCREMENT, at REAL, actor TEXT, area TEXT);
CREATE TABLE IF NOT EXISTS login_security(id INTEGER PRIMARY KEY CHECK(id=1), max_attempts INTEGER NOT NULL);
INSERT OR IGNORE INTO login_security VALUES(1,5);
CREATE TABLE IF NOT EXISTS account_lockouts(name TEXT PRIMARY KEY COLLATE NOCASE, failures INTEGER NOT NULL DEFAULT 0, locked_at TEXT);
CREATE TABLE IF NOT EXISTS receipt_categories(code TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS receipts(id TEXT PRIMARY KEY, at REAL, actor TEXT, category TEXT, filename TEXT, mime TEXT, body BLOB, source TEXT);
CREATE TABLE IF NOT EXISTS audit(at TEXT, actor TEXT, action TEXT, job TEXT);''')
        init_comms(c)
        init_workforce(c)
        init_pos(c)
        customer_init(c)
        catalog_init(c)
        hr_init(c)
        if 'chosen_on' not in {r[1] for r in c.execute('PRAGMA table_info(landing_preferences)')}:
            c.execute('ALTER TABLE landing_preferences ADD COLUMN chosen_on TEXT')
        c.execute('CREATE TABLE IF NOT EXISTS local_admin_sessions(token_hash TEXT PRIMARY KEY,name TEXT COLLATE NOCASE,version TEXT)')
        c.execute('CREATE TABLE IF NOT EXISTS permission_roles(id INTEGER PRIMARY KEY,name TEXT UNIQUE COLLATE NOCASE,body TEXT)')
        c.execute('CREATE TABLE IF NOT EXISTS user_roles(name TEXT PRIMARY KEY COLLATE NOCASE,role_id INTEGER)')
        c.execute('CREATE TABLE IF NOT EXISTS page_colors(id INTEGER PRIMARY KEY CHECK(id=1),body TEXT)')
        c.execute('CREATE TABLE IF NOT EXISTS sharing_settings(id INTEGER PRIMARY KEY CHECK(id=1),body TEXT)')
        c.execute('CREATE TABLE IF NOT EXISTS receipt_profiles(name TEXT PRIMARY KEY COLLATE NOCASE,profile_id TEXT UNIQUE)')
        for person in c.execute('SELECT name FROM users').fetchall():c.execute('INSERT OR IGNORE INTO receipt_profiles VALUES(?,?)',(person['name'],secrets.token_hex(16)))
        c.execute("""UPDATE user_profile_photos SET approved=pending,approved_revision=pending_revision,
                     pending=NULL,pending_revision=NULL,status='approved'
                     WHERE pending_revision IS NOT NULL AND account IN (
                       SELECT p.profile_id FROM receipt_profiles p JOIN users u ON u.name=p.name WHERE u.admin=1)""")
        pending_admin_requests=c.execute("""SELECT q.*,u.name FROM work_requests q
            JOIN receipt_profiles p ON p.profile_id=q.account JOIN users u ON u.name=p.name
            WHERE u.admin=1 AND q.status='pending' ORDER BY q.id""").fetchall()
        for request in pending_admin_requests:
            work_set_request_decision(c,request,'approved',request['name'])
        c.execute('CREATE TABLE IF NOT EXISTS receipt_details(receipt_id TEXT PRIMARY KEY,reimbursement INTEGER NOT NULL DEFAULT 0,guest_assigned INTEGER NOT NULL DEFAULT 0)')
        c.execute('CREATE TABLE IF NOT EXISTS receipt_ownership(receipt_id TEXT PRIMARY KEY,profile_id TEXT)')
        c.execute("INSERT OR IGNORE INTO receipt_ownership SELECT r.id,p.profile_id FROM receipts r LEFT JOIN receipt_profiles p ON p.name=r.actor AND r.actor!='Guest'")
        c.execute("CREATE TABLE IF NOT EXISTS appearance_preferences(name TEXT PRIMARY KEY COLLATE NOCASE, mode TEXT NOT NULL)")
        c.execute('CREATE TABLE IF NOT EXISTS journal_archives(file TEXT PRIMARY KEY, sha256 TEXT NOT NULL, records INTEGER NOT NULL, archived_at TEXT NOT NULL)')
        c.execute('CREATE TABLE IF NOT EXISTS user_grants(name TEXT PRIMARY KEY COLLATE NOCASE, body TEXT)')
        c.execute('CREATE TABLE IF NOT EXISTS connection_activity_settings(id INTEGER PRIMARY KEY CHECK(id=1), inactive_minutes INTEGER NOT NULL)')
        c.execute('CREATE TABLE IF NOT EXISTS app_migrations(name TEXT PRIMARY KEY)')
        if not c.execute("SELECT 1 FROM app_migrations WHERE name='schedule-view-default-v1'").fetchone():
            for row in c.execute('SELECT name,body FROM user_grants').fetchall():
                grants=json.loads(row['body']);grants['view_schedule']=True
                c.execute('UPDATE user_grants SET body=? WHERE name=?',(json.dumps(grants),row['name']))
            c.execute("INSERT INTO app_migrations VALUES('schedule-view-default-v1')")


