                kind={'/office-security':'text/html; charset=utf-8','/office-timekeeping':'text/html; charset=utf-8','/':'text/html; charset=utf-8','/mobile':'text/html; charset=utf-8','/mobile/':'text/html; charset=utf-8','/app.js':'text/javascript','/style.css':'text/css'}[self.path]
